def city_ui(city) -> dict:
    default = {"manager": "관리기관", "manager_inquiry": "관리기관", "merged_list": False,
               "merged_list": False, "district_short": False,
               "std_base_date": "", "realtime": False,
               "discount_note": "지자체 조례에 따라 감면율이 다릅니다. 현장 확인이 필요합니다.",
               "free_example": "", "calc_note": "차량 감면은 지자체 조례에 따라 다릅니다(현장 확인).",
               "daily_example": "1일 주차권 요금", "street_examples": "", "street_fee_caveat": "",
               "rate_bullets": None}
    ui = {**default, **CITY_UI.get(city["city"] if city else "", {})}
    # 기준일이 비어 있으면(CITY_UI에 항목은 있으나 std_base_date만 없는 도시 —
    #   공주시·보령시·청양군·태백시·삼척시·속초시·진도군 — 포함) 해당 도시 lots의
    #   최빈값으로 채운다 (점유율 50% 미만이면 빈 값 유지 — 그 경우 렌더링 지점에서
    #   문구 자체를 뺀다). 큐레이션된 CITY_UI 값이 있으면 우선한다.
    #   관리기관 추론은 종전대로 CITY_UI에 없는 도시만 대상으로 한다(큐레이션 값 보호).
    lots = (city or {}).get("_lots") or []
    if lots:
        n = len(lots)
        _bd = Counter(l.get("base_date") for l in lots if l.get("base_date")).most_common(1)
        if _bd and _bd[0][1] * 2 >= n and not ui.get("std_base_date"):
            ui["std_base_date"] = _bd[0][0]
        if (city or {}).get("city") not in CITY_UI:
            _mg = Counter(l.get("manager") for l in lots if l.get("manager")).most_common(1)
            if _mg and _mg[0][1] * 2 >= n and ui.get("manager") in ("", "관리기관"):
                ui["manager"] = _mg[0][0]
    return ui


def manager_ref(ui) -> str:
    """FAQ 문구의 관리기관 표기 — '관리기관(○○시청)' / 이름이 없으면 괄호 없이 '관리기관'만."""
    m = (ui.get("manager") or "").strip()
    return f"관리기관({m})" if m and m != "관리기관" else "관리기관"


def std_date_ref(ui) -> str:
    """'(데이터 기준일 2026-04-24)' — 기준일이 없으면 빈 문자열(괄호 자체를 뺀다)."""
    d = (ui.get("std_base_date") or "").strip()
    return f"(데이터 기준일 {d})" if d else ""


def std_date_suffix(ui) -> str:
    """', 기준일 2026-04-24' — 기준일이 없으면 빈 문자열."""
    d = (ui.get("std_base_date") or "").strip()
    return f", 기준일 {esc(d)}" if d else ""


def city_rows_total(city):
    """원자료에서 그 도시가 등록한 행 수(품질 리포트의 키 이름 차이를 흡수한다)."""
    q = city.get("quality") or {}
    for k in (f"원자료_{city['city']}행수", "원자료_행수"):
        if q.get(k) is not None:
            return q[k]
    return ""


def city_free_type_lots(city):
    """요금 구분이 '무료'인 주차장 수 — 주말에도 요금이 없다고 설명할 때 쓴다."""
    return city.get("quality", {}).get("요금구분", {}).get("무료", 0)


# ------------------------------------------------------- 자동 슬러그 (전국 확장)
# 국어의 로마자 표기법(문화체육관광부 고시)을 따르는 자동 슬러그 생성기.
#   · 이미 색인된 URL 은 GU_SLUG / DONG_SLUG / districts[].slug 매핑이 항상 우선하므로
#     수원시 39페이지 주소는 그대로 유지된다.
#   · 매핑에 없는 지역(다른 시·군·구·동)은 이름만으로 슬러그를 만들어 수동 딕셔너리 없이
#     같은 파이프라인에 편입할 수 있다.
#   · 음운 변화는 대표음(종성 ㄱ·ㄷ·ㅂ → k·t·p)과 ㄹ의 비음화·유음화만 반영한 간략 규칙이다.
CHO_ROM = ["g", "kk", "n", "d", "tt", "r", "m", "b", "pp", "s", "ss", "",
           "j", "jj", "ch", "k", "t", "p", "h"]
JUNG_ROM = ["a", "ae", "ya", "yae", "eo", "e", "yeo", "ye", "o", "wa", "wae", "oe",
            "yo", "u", "wo", "we", "wi", "yu", "eu", "ui", "i"]
JONG_ROM = ["", "k", "k", "k", "n", "n", "n", "t", "l", "k", "m", "l", "l", "l", "p",
            "l", "m", "p", "p", "t", "t", "ng", "t", "t", "k", "t", "p", "t"]
JONG_BIEUM = {1, 2, 3, 9, 24}      # ㄱ ㄲ ㄳ ㄺ ㅋ  → ㄹ 앞에서 [ŋ]
JONG_YUEUM = {4, 8}                # ㄴ ㄹ           → ㄹ 앞/뒤에서 [l]
CHO_N, CHO_R = 2, 5

ADMIN_SUFFIX = [("대로", "daero"), ("동", "dong"), ("읍", "eup"), ("면", "myeon"), ("리", "ri"),
                ("가", "ga"), ("길", "gil"), ("구", "gu"), ("시", "si"), ("군", "gun"), ("로", "ro"), ("도", "do")]


def romanize(text: str) -> str:
    """한글 문자열을 로마자로 옮긴다(한글 음절 단위, 음운 변화 일부 반영)."""
    chars = list(str(text or ""))
    out = []
    pending_cho = None          # 앞 음절의 영향으로 바뀐 다음 초성
    for i, ch in enumerate(chars):
        code = ord(ch)
        if not (0xAC00 <= code <= 0xD7A3):
            out.append(ch)
            pending_cho = None
            continue
        s = code - 0xAC00
        cho, jung, jong = s // 588, (s % 588) // 28, s % 28
        nxt = None
        if i + 1 < len(chars) and 0xAC00 <= ord(chars[i + 1]) <= 0xD7A3:
            nxt = (ord(chars[i + 1]) - 0xAC00) // 588

        jong_rom, cho_rom = JONG_ROM[jong], CHO_ROM[cho]
        if pending_cho is not None:
            cho_rom = pending_cho
        pending_cho = None
        if nxt == CHO_R:
            if jong in JONG_BIEUM:          # 백로 → baengno
                jong_rom, pending_cho = "ng", "n"
            elif jong in JONG_YUEUM:        # 신라 → silla
                jong_rom, pending_cho = "l", "l"
        out.append(cho_rom + JUNG_ROM[jung] + jong_rom)
    return "".join(out)


def base_slug(name: str) -> str:
    """행정 접미사를 분리해 소문자·하이픈 슬러그를 만든다. 예: 정자동 → jeongja-dong"""
    n = re.sub(r"\s+", "", str(name or ""))
    suffix = ""
    for tail, roman in ADMIN_SUFFIX:
        if n.endswith(tail) and len(n) - len(tail) >= 1:
            suffix, n = roman, n[: -len(tail)]
            break
    core = re.sub(r"[^a-z0-9]+", "-", romanize(n).lower()).strip("-")
    if not core:
        core = "x"
    return f"{core}-{suffix}" if suffix else core


def city_slug(city: str) -> str:
    """시·군 슬러그. 매핑이 없으면 이름으로 생성(성남시 → seongnam)."""
    if city in CITY_SLUG:
        return CITY_SLUG[city]
    core = base_slug(city)
    for suf in ("si", "gun", "gu"):
        if core.endswith("-" + suf):
            core = core[: -(len(suf) + 1)]
    return core or "region"


def gu_slug(gu: str, city: str = "수원시") -> str:
    """구 슬러그: 기존 매핑 우선, 없으면 시 슬러그 + 로마자(영통구 → suwon-yeongtong)."""
    if gu in GU_SLUG:
        return GU_SLUG[gu]
    core = base_slug(gu)
    for suf in ("gu", "gun", "si"):
        if core.endswith("-" + suf):
            core = core[: -(len(suf) + 1)]
    cs = city_slug(city)
    return f"{cs}-{core}" if core and core != cs else cs


def dong_slug(dong: str) -> str:
    """동 슬러그: 기존 매핑 우선, 없으면 로마자 자동 생성(정자동 → jeongja-dong)."""
    if dong in DONG_SLUG:
        return DONG_SLUG[dong]
    return base_slug(dong) or "etc"


def dong_slug_map(names) -> dict:
    """한 구 안에서 슬러그 충돌을 결정적으로 푸는 매핑(정렬 순서 고정)."""
    out, used = {}, set()
    for n in sorted(names):
        slug, k = dong_slug(n), 2
        while slug in used:
            slug = f"{dong_slug(n)}-{k}"
            k += 1
        used.add(slug)
        out[n] = slug
    return out


# ------------------------------------------------------------------ 경로
def is_city_wide(city) -> bool:
    """자치구가 없어 시 하나가 곧 지역 묶음인 도시인지(평택시).

    districts 에 시 이름 하나만 들어 있고 그 슬러그가 시 슬러그와 같으면, 시 페이지가
    계산기·목록 페이지를 겸한다(구 페이지를 따로 만들지 않는다).
    """
    ds = (city or {}).get("districts") or []
    return len(ds) == 1 and ds[0].get("name") == city.get("city") and ds[0].get("slug") == city.get("slug")


# 경기도의 군(가평군·양평군·연천군)과 부산 기장군 — 자치구·동 대신 읍·면이 지역 단위다.
COUNTY_CITIES = ("가평군", "양평군", "연천군", "부산 기장군", "대구 달성군", "대구 군위군",
                 "울산 울주군")


def is_county(city) -> bool:
    """자치구가 없는 군인지 — ‘동’ 대신 ‘읍·면’으로 적는다."""
    return (city or {}).get("city") in COUNTY_CITIES


def city_path(city) -> str:
    return f"/parking/{city['province_slug']}/{city['slug']}/"


def district_path(city, d) -> str:
    return f"/parking/{city['province_slug']}/{d['slug']}/"


def street_path(city) -> str:
    return f"{city_path(city)}street-parking/"


# ------------------------------------------------------------------ 상세페이지
# 큰 유료 주차장은 이름 검색(“○○주차장 월정기”)에 닿도록 개별 상세페이지를 만든다
# (운영자 결정 2026-11-20 — 시범이 아니라 대상 전부). 대상: 요금 구분이 ‘무료’가
# 아니고(유료·미상) 구획수가 기준 이상인 곳. 경로는 시 페이지 아래에 내부 id를 쓴다.
DETAIL_MIN_SPACES = 50


def is_detail_target(lot) -> bool:
    return lot["fee"]["type"] != "무료" and (lot.get("spaces") or 0) >= DETAIL_MIN_SPACES


def detail_path(city, lot) -> str:
    return f"{city_path(city)}{lot['id']}/"


_CITY_BY_NAME: dict = {}


def city_of(lot):
    """카드·표처럼 city dict가 손에 없는 렌더러에서 lot의 city dict를 찾는다.

    slug는 광역시 자치구끼리 겹친다(부산·대구·광주·울산 북구 전부 'buk-gu') —
    그래서 유일한 도시 이름(lot['city'], 예: '부산 북구')으로 찾는다.
    같은 도시명이 두 도에 있는 경우(경남·강원 고성군)는 도 슬러그까지 맞춘다.
    """
    if not _CITY_BY_NAME:
        _CITY_BY_NAME.update({(c["city"], c.get("province_slug")): c for c in SITE_CITIES})
    key = (lot.get("city") or "", lot.get("province_slug"))
    if key in _CITY_BY_NAME:
        return _CITY_BY_NAME[key]
    # province_slug가 없는 옛 lot은 도시명만으로 찾는다(하위 호환).
    for (name, _prov), c in _CITY_BY_NAME.items():
        if name == lot.get("city"):
            return c
    return None


# ------------------------------------------------------------------ utils
def esc(s) -> str:
    return html.escape(str(s if s is not None else ""), quote=True)


def won(n) -> str:
    if n is None:
        return "—"
    return f"{int(round(n)):,}원"


def hhmm(m):
    if m is None:
        return ""
    h, mi = divmod(int(m), 60)
    return f"{h:02d}:{mi:02d}"


def _overlap_minutes(a0, a1, b0, b1):
    return max(0, min(a1, b1) - max(a0, b0))


def _free_window_overlap(fw, o0, o1):
    # 무료 시간대는 자정을 넘길 수 있어(wrap) 기준일을 -1일·당일·+1일로 옮겨 본다.
    total = 0
    for k in (-1, 0, 1):
        f0 = fw["start"] + k * 1440
        f1 = (fw["end"] + 1440 if fw.get("wrap") else fw["end"]) + k * 1440
        total += _overlap_minutes(o0, o1, f0, f1)
    return total


def _chargeable_minutes(lot, minutes, day, entry):
    # entry(자정부터 분)가 없으면 예전처럼 이용 시간 전부를 과금 대상으로 본다.
    # chargeable = 운영시간과 겹치는 분 - 그 안에서 무료 시간대와 겹치는 분.
    # 자정을 넘는 체류는 선택한 요일 안에서만 과금한다(다음 날 분은 계산하지 않음).
    if entry is None:
        return minutes, minutes
    h = lot["hours"].get(day) or {}
    op_start, op_end = 0, 1440
    if not h.get("24h") and h.get("start") is not None and h.get("end") is not None:
        op_start, op_end = h["start"], h["end"]
    s0, s1 = entry, entry + minutes
    op = _overlap_minutes(s0, s1, op_start, op_end)
    free = 0
    if lot.get("free_window_min"):
        o0, o1 = max(s0, op_start), min(s1, op_end)
        if o1 > o0:
            free = _free_window_overlap(lot["free_window_min"], o0, o1)
    return max(0, op - free), op


def price_for(lot, minutes=120, day="weekday", rate=0.0, exempt=0, entry=None):
    """JS 계산기와 동일한 규칙 (서버 선계산용).

    entry 는 입차 시각(자정부터 분). None이면 예전처럼 이용 시간 전부를 과금 대상으로
    본다(cheap_lede·표 등 입차 시각이 없는 호출은 이 기본값을 쓴다).
    exempt 는 조례상 '면제 시간'(분). 과금 대상 시간이 exempt 이내면 0원(면제),
    넘으면 rate 만큼 감면한 금액을 낸다. 예: 성남 장애인 1시간 면제 후 50%.
    fee['steps'] 가 있으면 시간대별 누진 할증(안양시), fee['free_min'] 은 최초 무료 시간,
    fee['cap_fee'] 는 일일 최대요금(상한)이다.
    fee['deduct_min'] 은 ‘최초 N분 무료’ 정책 시간(김포시 1시간 무료)으로, 조례가 ‘감면은
    한 가지만’이라고 정한 도시에서는 그 시간을 뺀 요금과 감면율을 적용한 요금 가운데
    싼 쪽을 쓴다.
    """
    if lot.get("bus_only"):
        # 관광버스 전용 — 승용차 요금 계산에서 제외한다.
        return {"state": "bus_only"}
    if not lot["oper"].get(day):
        return {"state": "closed"}
    fee = lot["fee"]
    if fee["type"] == "무료" or (day != "weekday" and lot["free_days"].get(day)):
        return {"state": "free"}
    chargeable, op_overlap = _chargeable_minutes(lot, minutes, day, entry)
    if exempt and chargeable > 0 and chargeable <= exempt:
        return {"state": "free", "exempt": True, "exempt_min": exempt}
    if fee.get("flat_day"):
        # 종일 정액(금오산·단양 관광지 등) — 시간 요금 없이 어떤 이용 시간에도 정액이다.
        # 입차 시각과 무관하므로 과금 구간 계산보다 먼저 본다. 감면은 정액에도 붙는다(P1-1).
        _flat = fee["base_fee"] if fee["base_fee"] is not None else fee["daily_fee"]
        if rate > 0:
            _disc = int(math.floor(_flat * (1 - rate) + 0.5))
            if _disc < _flat:
                return {"state": "paid", "amount": _disc, "before": _flat,
                        "capped": False, "discounted": True, "deducted": False, "flat": True}
        return {"state": "paid", "amount": _flat, "before": _flat,
                "capped": False, "discounted": False, "deducted": False, "flat": True}
    # 과금 대상 시간이 0분이면 운영시간 밖이다. 노상은 그 시간에 무료, 그 밖은 휴무로 본다.
    if chargeable == 0:
        if op_overlap == 0:
            return ({"state": "free", "outside_hours": True} if lot.get("ptype") == "노상"
                    else {"state": "closed", "outside_hours": True})
        return {"state": "free", "free_window": True}   # 과금 구간이 전부 무료 시간대(운영시간 안)
    if fee["type"] != "유료" or not fee["base_min"] or fee["base_fee"] is None:
        return {"state": "unknown"}
    free_min = fee.get("free_min") or 0
    if free_min and chargeable <= free_min:
        return {"state": "free", "free_min": free_min}
    # 최초 N분 무료 정책(김포시 1시간 무료) — 그 시간 이내는 0원이다.
    if (fee.get("deduct_min") or 0) and chargeable <= fee["deduct_min"]:
        return {"state": "free", "deducted": True, "deduct_min": fee["deduct_min"]}

    def raw_charge(mins):
        """그 시간만큼 주차했을 때의 요금과 1일 상한 적용 여부."""
        if fee.get("bands"):
            # 구간 요금(의왕시 행락지) — 머문 시간이 속한 구간의 금액을 받는다.
            raw = next((b["amount"] for b in fee["bands"]
                        if b.get("until") is None or mins <= b["until"]),
                       fee["bands"][-1]["amount"])
        elif fee.get("steps"):
            raw, t = fee["base_fee"], fee["base_min"]
            while t < mins:
                step = next((st for st in fee["steps"]
                             if st.get("until") is None or t < st["until"]), fee["steps"][-1])
                raw += step["unit_fee"]
                # 단계마다 단위 시간이 다를 수 있다(세종 — 2시간까지 10분, 2시간 초과 15분).
                t += step.get("unit_min") or fee.get("unit_min") or 10
        else:
            if mins <= fee["base_min"]:
                raw = fee["base_fee"]
            else:
                raw = fee["base_fee"] + math.ceil((mins - fee["base_min"]) / fee["unit_min"]) * fee["unit_fee"]
        capped = False
        cap = fee.get("cap_fee")
        if cap and raw > cap:
            raw, capped = cap, True
        elif fee["daily_fee"] and raw > fee["daily_fee"]:
            raw, capped = fee["daily_fee"], True
        return raw, capped

    if not fee.get("bands") and (not fee["unit_min"] or fee["unit_fee"] is None):
        return {"state": "unknown"}
    base_raw, base_capped = raw_charge(chargeable)
    best_raw, best_capped, deducted = base_raw, base_capped, False
    deduct = fee.get("deduct_min") or 0
    if deduct and chargeable > deduct:
        d_raw, d_capped = raw_charge(chargeable - deduct)
        if d_raw < best_raw:
            best_raw, best_capped, deducted = d_raw, d_capped, True
    discounted = False
    if rate > 0:
        # JS(Math.round)와 같은 반올림 — 0.5원은 올림(파이썬 round 는 짝수 반올림이라 262.5→262).
        r_raw = int(math.floor(base_raw * (1 - rate) + 0.5))
        if r_raw < best_raw:
            best_raw, best_capped, deducted, discounted = r_raw, base_capped, False, True
    return {"state": "paid", "amount": best_raw, "before": round(base_raw),
            "capped": best_capped, "discounted": discounted, "deducted": deducted}


def hours_text(lot) -> str:
    hs = lot["hours"]
    if lot.get("city") == "양평군" and lot["fee"]["type"] != "무료":
        # 양평군은 주간 운영시간에만 요금을 받고 야간·공휴일은 무료다(조례 별표1 비고1).
        return (f"24시간 개방 · 주차요금 {hhmm(hs['weekday']['start'])}~{hhmm(hs['weekday']['end'])}"
                f" · 야간·일요일·공휴일 무료")
    if lot.get("city") == "가평군" and lot["fee"]["type"] != "무료":
        # 가평군은 연중 24시간 열고 주차요금만 09:00~18:00에 받는다(조례 제10조①).
        if lot["fee"].get("flat_day"):
            return f"24시간 개방 · 일일주차권 {won(lot['fee']['daily_fee'])}"
        return (f"24시간 개방 · 주차요금 {hhmm(hs['weekday']['start'])}~"
                f"{hhmm(hs['weekday']['end'])}")
    all24 = all(hs[k]["open"] and hs[k]["24h"] for k in ("weekday", "sat", "sun"))
    if all24:
        # 의왕시는 24시간 열되 주말·공휴일에 무료로 개방하는 주차장이 있다(청계산).
        if (lot.get("city") == "의왕시" and lot["fee"]["type"] != "무료"
                and (lot["free_days"].get("sat") or lot["free_days"].get("sun"))):
            return "24시간 운영(연중) · 토·일·공휴일 무료 개방"
        return "24시간 운영(연중)"
    parts = []
    # 양주시·포천시는 조례 별표1 비고가 야간·주말·공휴일 주차요금을 받지 않는다고 정한다 —
    #   요금을 받지 않는 요일은 ‘24시간’ 대신 ‘무료 개방’으로 적는다.
    free_weekend_city = (lot.get("city") in ("양주시", "포천시", "의왕시", "여주시", "동두천시",
                                             "과천시", "미추홀구", "연수구", "남동구", "제물포구",
                                             "영종구", "부산 서구", "부산 부산진구")
                         and lot["fee"]["type"] != "무료")
    for k, label in (("weekday", "평일"), ("sat", "토"), ("sun", "일·공휴일")):
        h = hs[k]
        if not h["open"]:
            parts.append(f"{label} 휴무")
        elif h.get("note_open"):
            # 특기사항에 개방만 적히고 운영시간은 등록돼 있지 않은 날(부천시 부설 등)
            parts.append(f"{label} 개방(시간 미등록)")
        elif free_weekend_city and k in ("sat", "sun") and lot["free_days"].get(k):
            parts.append(f"{label} 무료 개방")
        elif h["24h"]:
            parts.append(f"{label} 24시간")
        else:
            parts.append(f"{label} {hhmm(h['start'])}~{hhmm(h['end'])}")
    return " · ".join(parts)


def rate_text(fee) -> str:
    """‘기본 30분 600원 · 이후 10분마다 300원’ 같은 요율 문장.

    누진 요금표(안양시)는 시간대별 요율을 화살표로 모두 적는다.
    """
    if fee.get("bands"):
        bands = fee["bands"]
        first = (f"최초 {fee['free_min']}분 무료" if fee.get("free_min") else "")
        parts = []
        prev = None
        for b in bands:
            until, amount = b.get("until"), b["amount"]
            if until is None:
                parts.append(f"{prev // 60}시간 초과 {won(amount)}")
            elif prev is None:
                parts.append(f"{until // 60}시간 이내 {won(amount)}")
            else:
                parts.append(f"{prev // 60}~{until // 60}시간 {won(amount)}")
            prev = until
        return (" · ".join(x for x in (first, " / ".join(parts)) if x)
                + " (머문 시간이 속한 구간의 금액)")
    if fee.get("steps") and fee.get("steps_label_only"):
        # 세종 — 단계마다 단위 시간이 달라 ‘10분마다 300→500’처럼 적으면 오해를 산다. 데이터가 적어 둔
        #   한 줄 설명(steps_label)을 그대로 쓴다.
        first = (f"최초 {fee['free_min']}분 무료" if (not fee["base_fee"] and fee.get("free_min"))
                 else f"기본 {fee['base_min']}분 {won(fee['base_fee'])}")
        return first + " · " + (fee.get("steps_label") or "누진 요금")
    if fee.get("steps"):
        rates = []
        for st in fee["steps"]:
            if st["unit_fee"] not in rates:
                rates.append(st["unit_fee"])
        first = (f"최초 {fee['free_min']}분 무료" if (not fee["base_fee"] and fee.get("free_min"))
                 else f"기본 {fee['base_min']}분 {won(fee['base_fee'])}")
        return (first + f" · 이후 {fee.get('unit_min') or 10}분마다 "
                + "→".join(won(r) for r in rates)
                + f" ({fee.get('steps_label') or '시간대별 누진'})")
    if not fee["base_fee"] and fee.get("free_min"):
        # 기본요금 없이 최초 N분 무료 뒤 바로 요율이 붙는 요금(평택시 1급지 90분 무료)
        return (f"최초 {fee['free_min']}분 무료 · 이후 "
                f"{fee['unit_min']}분마다 {won(fee['unit_fee'])}")
    return (f"기본 {fee['base_min']}분 {won(fee['base_fee'])} · 이후 "
            f"{fee['unit_min']}분마다 {won(fee['unit_fee'])}")


def fee_text(lot) -> str:
    f = lot["fee"]
    if lot.get("bus_only"):
        return "관광버스 전용 · 승용차 주차 불가"
    if f["type"] == "미상":
        return "요금 정보 없음 · 현장 확인"
    if f["type"] == "무료":
        return "무료"
    if f.get("monthly_only"):
        # 아산시 캠핑용자동차 전용주차장 — 월정기 전용(시간제 없음).
        return (f"월정기 전용 · 월 {won(f['monthly'])}"
                + (f"({f['monthly_label']})" if f.get("monthly_label") else ""))
    if f.get("grade_label") == "청사 부설" and f.get("free_min"):
        # 여주시 시청부설주차장 — 최초 40분 무료 → 40분 초과 1시간 이내 500원 → 1시간 초과 10분당 300원.
        return (f"최초 {f['free_min']}분 무료 · {f['free_min']}분 초과 1시간 이내 {won(f['base_fee'])}"
                f" · 1시간 초과 {f['unit_min']}분당 {won(f['unit_fee'])}")
    if f.get("free_block"):
        # 울주군 ‘최초 120분 무료’ 요금표 — 120분까지 0원, 그 뒤 기본요금에 10분 단위 요금이 붙는다.
        bits = [f"최초 {f['free_min']}분 무료", f"{f['free_min']}분 초과 기본 {won(f['base_fee'])}"]
        if f["unit_min"] and f["unit_fee"] is not None:
            bits.append(f"이후 {f['unit_min']}분당 {won(f['unit_fee'])}")
        if f["daily_fee"]:
            bits.append(f"1일권 {won(f['daily_fee'])}")
        if f["monthly"]:
            bits.append(f"월 {won(f['monthly'])}" + (f"({f['monthly_label']})" if f.get("monthly_label") else ""))
        return " · ".join(bits)
    if f.get("flat_day"):
        # 파주시 관광지 주차장 — 시간 요금 없이 종일 정액(감악산·마장호수·임진각 2,000원).
        bits = [f"종일 {won(f['base_fee'])}"]
        if f.get("deduct_min") or f.get("free_min"):
            bits.append(f"최초 {f.get('deduct_min') or f.get('free_min')}분 무료")
        return " · ".join(bits)
    if f.get("bands"):
        bands = f["bands"]
        bits = []
        if f.get("free_min"):
            bits.append(f"최초 {f['free_min']}분 무료")
        prev = None
        for b in bands:
            until, amount = b.get("until"), b["amount"]
            if until is None:
                bits.append(f"{prev // 60}시간 초과 {won(amount)}")
            elif prev is None:
                bits.append(f"{until // 60}시간 이내 {won(amount)}")
            else:
                bits.append(f"{prev // 60}~{until // 60}시간 {won(amount)}")
            prev = until
        if f.get("daily_fee"):
            bits.append(f"1일권 {won(f['daily_fee'])}")
        if f.get("monthly"):
            bits.append(f"월 {won(f['monthly'])}")
        return " · ".join(bits)
    if f.get("monthly_only"):
        # 천안 목천 캠핑카전용주차장 — 월정기 전용(시간제 없음).
        return (f"월정기 전용 · 월 {won(f['monthly'])}"
                + (f"({f['monthly_label']})" if f.get("monthly_label") else ""))
    # 기본요금 없이 최초 N분 무료 뒤 요율이 붙는 요금(평택시 1급지 90분 무료)은 그렇게 적는다.
    free_first = (not f["base_fee"] and f.get("free_min"))
    bits = [f"최초 {f['free_min']}분 무료" if free_first
            else f"기본 {f['base_min']}분 {won(f['base_fee'])}"]
    if f.get("steps") and f.get("steps_label_only"):
        # 울산 — 30분 단위 안에서 10분 이내·20분 이내·30분 이내로 오르는 요금은 증분이 되풀이되어
        #   200→200→100 처럼 적으면 오해를 산다. 데이터가 적어 둔 한 줄 설명을 그대로 쓴다.
        bits.append(f.get("steps_label") or "누진")
    elif f.get("steps"):
        rates = []
        for st in f["steps"]:
            if st["unit_fee"] not in rates:
                rates.append(st["unit_fee"])
        bits.append(f"이후 {f.get('unit_min') or 10}분당 " + "→".join(won(r) for r in rates)
                    + f" ({f.get('steps_label') or '누진'})")
    elif f["unit_min"] and f["unit_fee"] is not None:
        bits.append(f"추가 {f['unit_min']}분 {won(f['unit_fee'])}")
    free_written = None
    if f.get("free_min") and not free_first:
        bits.append(f"최초 {f['free_min']}분 무료")
        free_written = f["free_min"]
    if f.get("deduct_min") and f["deduct_min"] != free_written:
        # 주차장별 ‘무료이용시간·회차시간’(파주시 10~120분) — 그 시간을 뺀 나머지로 계산한다.
        #   free_min 과 같은 시간을 두 번 적지 않는다(김포·이천·안성처럼 둘 다 넣은 도시).
        bits.append(f"최초 {f['deduct_min']}분 무료")
    if f.get("cap_fee"):
        cap_label = "(조례 상한)" if f.get("cap_src") == "조례 상한" else ""
        bits.append(f"일일 최대 {won(f['cap_fee'])}{cap_label}")
    if f["daily_fee"]:
        # 안산시는 1일 주차권이 아니라 ‘1일 주차요금(상한)’이라 그 이름으로 적는다.
        day_label = ("1일 주차요금" if f.get("cap_src") == "조례 1일 주차요금"
                     else "12시간권" if f.get("cap_src") == "12시간권(선불)"
                     else "12시간 최대" if f.get("cap_src") == "12시간 한도"
                     else "1일권")
        bits.append(f"{day_label} {won(f['daily_fee'])}"
                    + (f"({f['daily_hours']}시간)" if f["daily_hours"]
                       and day_label not in ("12시간권", "12시간 최대") else ""))
    if f.get("prepaid_day"):
        bits.append(f"선불 1일 {won(f['prepaid_day'])}")
    if f["monthly"]:
        bits.append(f"월 {won(f['monthly'])}" + (f"({f['monthly_label']})" if f.get("monthly_label") else ""))
    return " · ".join(bits)


def addr_text(lot) -> str:
    a = lot["addr_jibun"] or lot["addr_road"]
    if a:
        return a
    dong = lot["dong"] or lot.get("city", "주소")
    return f"상세 주소 미제공 · {dong} 인근(지도 좌표 기준)"


# ---------------------------------------------------------------- 지도 링크 (T-04, T-04b)
# 공공데이터 좌표가 실제 주차장이 아닌 곳(호수·공원 안, 같은 단지의 다른 주차장 자리)을
# 가리키는 곳이 있어, 카카오맵·구글맵 장소로 확인한 좌표로 지도 링크만 덮어쓴다.
# (site.json 좌표는 원자료 그대로 두어 계산·동 추정 로직에는 영향이 없게 한다)
MAP_COORD_FIX = {
    # 수원시 장안구 만석공원: 다섯 곳이 모두 송죽동 417-23(공원) 좌표를 공유해
    # 제1~5가 같은 지점에 찍혔다. 아래는 카카오맵·구글맵 장소 좌표.
    "std-057": (37.3018787, 126.9988270),   # 만석공원 제1 → 만석 제1공영주차장(송죽동 286-1)
    "std-055": (37.3024157, 127.0022592),   # 만석공원 제2 → 만석공원 제2공영주차장(송죽동 228)
    "std-053": (37.3013984, 127.0036826),   # 만석공원 제3 → 만석 제3공영주차장(송죽동 318)
    "std-051": (37.2997684, 127.0047202),   # 만석공원 제4 → 만석공원 제4공영주차장(송죽동 346-6)
    "std-058": (37.2973181, 126.9998638),   # 만석공원 제5 → 만석공원 제5공영주차장(송죽동 417-24, 구글 지도 장소 좌표)
    # 수원시 영통구 광교호수공원: 원자료 좌표가 호수 물가(전기차충전소) 자리라
    # 핀이 호수에 찍혔다. 아래는 카카오맵·구글맵 주차장 장소 좌표.
    "std-007": (37.2767068, 127.0663223),   # 원천호수 → 광교호수공원 원천호수주차장(하동 1024)
    "std-009": (37.2848344, 127.0777866),   # 신대호수 → 광교호수공원 신대호수주차장(하동 1008)
}

# 등록 주소가 실제 위치와 다른 곳을 가리키는 노상 구간 — 노상 표는 주소 검색 링크를
# 쓰므로 stale 주소로 연결하면 4~6km 어긋난 곳으로 간다. 이 구간만 좌표 핀 링크로
# 나간다(T-03 후속, Instinct 2026-11-19). 좌표는 지오코딩 오버레이 검증값이다.
STALE_ADDR_LINK_IDS = {
    "cj-cheongju-s218",  # 메타바이오메드부근 — 등록 주소 과학산업3로 68-6, 실제 메타바이오메드 본사 자리
    "cj-cheongju-s228",  # 오창시외버스터미널 — 등록 주소 두릉유리로 1137-1, 실제 청주북부터미널 자리
}

# 이름에 이미 들어 있으면 덧붙이지 않는 말
PARKING_WORDS = ("주차장", "주차타워", "주차빌딩", "차고지")


def map_label(lot) -> str:
    """지도에 표시할 이름. '원천호수'처럼 주차장이라는 말이 없는 이름은
    지도 핀에 호수·공원 이름만 뜨므로 '공영주차장'을 붙인다.
    카카오 /link/map/ 은 쉼표로 이름·위도를 나누므로 이름 안의 쉼표는 '·'로 바꾼다."""
    name = lot["name"].strip().replace(",", "·")
    if any(w in name for w in PARKING_WORDS):
        return name
    if name.endswith(("공영", ")")):   # 곡반2공영 → 곡반2공영주차장, 마평동 공영(1) → …(1) 주차장
        return name + "주차장"
    if lot.get("ptype") == "부설":     # 시청정문 → 시청정문 주차장
        return name + " 주차장"
    return name + " 공영주차장"


def map_coords(lot):
    fix = MAP_COORD_FIX.get(lot["id"])
    if fix:
        return fix
    return lot["lat"], lot["lng"]


def map_links(lot):
    """카카오·네이버 지도 링크.

    카카오: /link/map/{이름},{위도},{경도} — 지정한 좌표에 이름표가 달린 핀을 찍는다.

    네이버: /?lat={위도}&lng={경도}&dlevel=12&title={이름} — 좌표에 이름표가 달린
      핀과 주소 카드를 띄운다. 이전 형식(/p?c={경도},{위도},16,0,0,0,dh)은 모바일에서
      앱 링크 페이지(m.map.naver.com/appLink.naver?…&appTargetPage=map&app=Y)로 넘어가
      지도 앱이 '중심만 맞춘 화면'으로 열렸고 핀·이름이 없었다(T-04b, 2026-11-17 확인).
      lat/lng/title 형식은 리다이렉트가 다르다(같은 날 curl로 확인):
        · PC    → map.naver.com/p/?title=…&lng=…&lat=…&zoom=16 (핀+이름+주소 카드)
        · 모바일 → m.map.naver.com/map?lat=…&lng=…&dlevel=12&title=… (핀+이름 카드)
      dlevel=12는 앱·웹 공통으로 줌 16에 해당한다(dlevel+4).
    좌표가 없는 주차장은 ?query=…&menu=location 검색 링크로 대체한다
    (/p/search/… 는 모바일에서 appTargetPage=search 앱 링크로 넘어간다).
    """
    label = map_label(lot)
    lat, lng = map_coords(lot)
    city = lot.get("city", "")
    addr = (lot.get("addr_road") or lot.get("addr_jibun") or "").strip()
    if lat and lng:
        kakao = f"https://map.kakao.com/link/map/{quote(label)},{lat},{lng}"
        naver = f"https://map.naver.com/?lat={lat}&lng={lng}&dlevel=12&title={quote(label)}"
    else:
        # 좌표가 없는 주차장은 이름 + 도로명주소(없으면 지번·시·군)로 검색한다.
        # 카카오는 map.kakao.com/link/search 모바일 접속이 앱 설치 안내(applink)로 넘어가므로
        # 모바일 지도 호스트(m.map.kakao.com/?q=)를 쓴다 — 데스크톱·모바일 모두 200 으로 지도가 열린다.
        query = " ".join(x for x in (label, addr or city) if x)
        kakao = f"https://m.map.kakao.com/?q={quote(query)}"
        naver = f"https://map.naver.com/?query={quote(query)}&menu=location"
    return kakao, naver


def free_note(lot):
    """무료 개방 관련 표기 문장."""
    if lot["fee"].get("category") == "resident":
        # 하남시 주거지 전용(거주자우선주차) 구역 — 주간 무료 개방, 야간 거주자 전용.
        return ("주거지 전용(거주자우선주차) — 주간 09:00~18:00 무료 개방, 야간은 거주자 전용"
                " (거주자 정기권 주간·야간 20,000원·전용 24시간 30,000원)")
    if lot["fee"]["type"] == "무료":
        return "원자료상 요금 구분이 '무료'입니다."
    if lot.get("city") == "공주시" and lot["free_days"].get("sun"):
        # 공주시는 일요일만 무료(조례 별표1 비고 4) — 공휴일 무료 개방 조항은 조례에 없다.
        return "일요일 무료 개방 (공주시 조례 별표1 비고 4 기준)"
    out = []
    if lot["free_days"].get("sun"):
        out.append("일요일·공휴일 무료 개방")
    if lot["free_days"].get("sat"):
        out.append("토요일 무료 개방")
    if out:
        # 시흥시는 특기사항이 아니라 조례·공영주차 포털의 공휴일 무료 개방 규정으로 정한 값이다.
        src = ("광명도시공사·광명시 안내 기준" if lot.get("city") == "광명시"
               else "구리시 홈페이지 안내 기준" if lot.get("city") == "구리시"
               else "시흥시 조례·공영주차 포털 기준" if lot.get("city") == "시흥시"
               else "김포시 조례 별표1 기준" if lot.get("city") == "김포시"
               else "파주시 통합주차 포털 기준" if lot.get("city") == "파주시"
               else "양주시 조례 별표1 비고3 기준" if lot.get("city") == "양주시"
               else "포천시 조례 별표1 비고5·포천도시공사 안내 기준" if lot.get("city") == "포천시"
               else "의왕도시공사 요금안내 기준" if lot.get("city") == "의왕시"
               else "여주도시공사 유료 운영시간 기준" if lot.get("city") == "여주시"
               else "동두천시 조례 별표1·공단 운영시간 기준" if lot.get("city") == "동두천시"
               else "양평군 조례 별표1 비고1 기준" if lot.get("city") == "양평군"
               else "원자료 특기사항 기준")
        return " · ".join(out) + f" ({src})"
    return None


def is_free_lot(lot) -> bool:
    return lot["fee"]["type"] == "무료" or lot["free_days"]["sat"] or lot["free_days"]["sun"]


def capa_note(lot) -> str:
    """구획수(표준데이터 등록면수)와 실시간 스냅샷 총면수가 다를 때의 짧은 설명.

    두 값은 기준이 다르다. 예: 매탄4지구는 구획 60면으로 등록됐지만
    스냅샷 합계는 58면이다. 두 숫자가 한 카드에 같이 나오면 모순처럼 보이므로
    차이를 숫자로 밝힌다.
    """
    rt = lot.get("realtime") or {}
    spaces, total = lot.get("spaces") or 0, rt.get("total") or 0
    if not (spaces and total) or spaces == total:
        return ""
    return f"등록 구획 {spaces:,}면과 {abs(total - spaces):,}면 차이"


def district_sorted(lots):
    """구(시) 페이지 카드 목록의 정렬 순서 — 무료 → 기본요금 → 이름.

    카드의 id(lot-1, lot-2…)와 다른 페이지의 링크(#lot-N)가 같은 주차장을 가리키도록
    build_district 와 build_city 가 이 순서를 함께 쓴다.
    """
    return sorted(lots, key=lambda l: (
        0 if is_free_lot(l) else 1,
        l["fee"]["base_fee"] if l["fee"]["type"] == "유료" and l["fee"]["base_fee"] is not None else 9_999_999,
        l["name"]))


def stats_for(lots):
    paid = [l["fee"]["base_fee"] for l in lots
            if l["fee"]["type"] == "유료" and l["fee"]["base_fee"]]
    return {
        "n": len(lots),
        "spaces": sum(l["spaces"] or 0 for l in lots),
        "free": len([l for l in lots if is_free_lot(l)]),
        "sun_free": len([l for l in lots if l["free_days"]["sun"] or l["fee"]["type"] == "무료"]),
        "sat_free": len([l for l in lots if l["free_days"]["sat"] or l["fee"]["type"] == "무료"]),
        "avg_base": round(sum(paid) / len(paid)) if paid else None,
        "unknown_fee": len([l for l in lots if l["fee"]["type"] == "미상"]),
        "closed_sat": len([l for l in lots if not l["oper"]["sat"]]),
        "closed_sun": len([l for l in lots if not l["oper"]["sun"]]),
        "live": len([l for l in lots if l.get("realtime")]),
        "capa_gap": len([l for l in lots if capa_note(l)]),
    }


# ------------------------------------------------------------------ jsonld
# 랜딩 페이지의 시·도 묶음 앵커 — BreadcrumbList 중간 항목의 주소로 쓴다.
PROVINCE_ANCHOR = {"경기도": "/#gyeonggi", "서울특별시": "/#seoul", "인천광역시": "/#incheon", "부산광역시": "/#busan",
                   "대구광역시": "/#daegu", "대전광역시": "/#daejeon", "광주광역시": "/#jeonnam",
                   "울산광역시": "/#ulsan", "세종특별자치시": "/#sejong", "제주특별자치도": "/#jeju"}


def jsonld_breadcrumb(items, page_path=None):
    """BreadcrumbList — 모든 ListItem 에 유효한 item(절대 URL)을 넣는다.

    구글 서치콘솔은 ListItem 에 item 이 비어 있으면 ‘item 입력란 누락’ 오류로 본다.
    그래서 화면용 breadcrumb 이 경로 없이(시·도 묶음) 또는 빈 문자열(현재 페이지)로
    되어 있어도, 구조화 데이터에는 시·도 앵커와 그 페이지의 canonical 경로를 넣는다.
    """
    out = []
    last = len(items) - 1
    for i, (name, path) in enumerate(items):
        if path:
            target = path
        elif path == "" and i == last:
            target = page_path or "/"
        else:
            target = PROVINCE_ANCHOR.get(name, "/")
        if not target.startswith("/"):
            target = "/" + target
        out.append({"@type": "ListItem", "position": i + 1, "name": name,
                    "item": SITE_BASE + target})
    return {"@context": "https://schema.org", "@type": "BreadcrumbList",
            "itemListElement": out}


def jsonld_itemlist(lots, path):
    return {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "name": "공영주차장 목록",
        "numberOfItems": len(lots),
        "itemListOrder": "https://schema.org/ItemListOrderAscending",
        "itemListElement": [
            {"@type": "ListItem", "position": i + 1,
             "name": lot["name"],
             "url": f"{SITE_BASE}{path}#lot-{i + 1}"}
            for i, lot in enumerate(lots)
        ],
    }


def jsonld_link_itemlist(name, items):
    """허브 페이지용 ItemList — 개별 주차장이 아니라 페이지에 실제로 있는
    지역 카드 링크(이름·URL)만 넣는다. items 는 (표시 이름, 절대 경로) 쌍."""
    return {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "name": name,
        "numberOfItems": len(items),
        "itemListOrder": "https://schema.org/ItemListOrderAscending",
        "itemListElement": [
            {"@type": "ListItem", "position": i + 1,
             "name": label,
             "url": f"{SITE_BASE}{href}"}
            for i, (label, href) in enumerate(items)
        ],
    }


def jsonld_faq(qa, path):
    return {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
            {"@type": "Question", "name": q,
             "acceptedAnswer": {"@type": "Answer", "text": a}}
            for q, a in qa
        ],
    }


def script_jsonld(objs):
    return "\n".join(
        '<script type="application/ld+json">' + json.dumps(o, ensure_ascii=False) + "</script>"
        for o in objs if o
    )


# ------------------------------------------------------------------ layout
def nav_html(city, url, nav_active) -> str:
    """상단 메뉴 — 한 줄 유지: 지역 이동 버튼 + 무료 개방 + 소개 + 문의.

    83개 지역 칩을 그리던 예전 메뉴는 모바일에서 여러 줄로 늘어나 헤더가 화면을 덮었고,
    그 다음의 <select> 콤보박스는 기본 모양이 디자인과 안 맞는다는 운영자 지적이 있었다
    (2026-11-24). '지역 이동' pill 버튼을 누르면 시·도 칩 패널이 헤더 아래에 열리고,
    도를 누르면 그 도 허브로 이동한다 — 깊은 지역 페이지에서도 한 번에 돌아갈 수 있다.
    모든 시·군·구 페이지 링크는 푸터의 지역 디렉터리와 /parking/regions/ 에
    그대로 남겨 색인 경로를 유지한다.
    """
    prov_links = []
    for prov in PROVINCE_ORDER:
        if prov == "광주광역시":
            continue  # 전남광주통합특별시 칩에 합산 — 별도 칩을 두지 않는다.
        cities = [c for c in SITE_CITIES if (c.get("province") or "지역") == prov]
        if not cities:
            continue
        _pslug = next((c.get("province_slug") for c in cities if c.get("province_slug")), "")
        _pn = sum(len(c.get("_card_lots") or []) for c in cities)
        if _pslug == "jeonnam":
            # 전남광주통합특별시 허브는 광주광역시 5개 구도 합산한다(build_province_hub와
            # 같은 기준) — 패널 숫자도 허브 제목(1,473곳)과 맞춘다.
            _pn += sum(len(c.get("_card_lots") or []) for c in SITE_CITIES
                       if (c.get("province") or "지역") == "광주광역시")
        prov_links.append(f'<a href="{url(province_path(_pslug))}">{esc(prov)} <small>{_pn:,}곳</small></a>')

    def cls(key):
        return ' class="on"' if nav_active == key else ""

    return (f'<nav class="site-nav" aria-label="주요 메뉴">'
            f'<span class="nav-jump"><button type="button" class="nav-jump-btn" id="region-jump-btn" '
            f'aria-expanded="false" aria-controls="region-jump-panel">지역 이동</button></span>'
            f'<a href="{url("/parking/free/")}"{cls("free")}>무료 개방</a>'
            f'<a href="{url("/about/")}"{cls("about")}>소개</a>'
            f'<a href="{url("/contact/")}"{cls("contact")}>문의</a>'
            f'</nav>'
            f'<div class="jump-panel" id="region-jump-panel" hidden>'
            f'<p class="jump-panel-t">다른 지역으로 이동</p>{"".join(prov_links)}</div>')


def footer_directory(url) -> str:
    """푸터 지역 디렉터리 — 시·도별 모든 시·군·구 링크(색인 경로 유지)."""
    blocks = []
    for prov in PROVINCE_ORDER:
        cities = [c for c in SITE_CITIES if (c.get("province") or "지역") == prov]
        if not cities:
            continue
        _slug = next((c.get("province_slug") for c in cities if c.get("province_slug")), "")
        links = " · ".join(f'<a href="{url(city_path(c))}">{esc(c["city"])}</a>' for c in cities)
        blocks.append(f'<p><b><a href="{url(province_path(_slug))}">{esc(prov)}</a></b> {links}</p>')
    # 푸터 곳수도 홈 히어로와 같은 전체 lots 기준(노상 구간 포함) — 카드 대상만 세면
    # 본문 숫자(17,398곳)와 어긋난다 (2026-11-24 정정).
    total = sum(len(c.get("_lots") or []) for c in SITE_CITIES)
    return ('<details class="foot-dir">'
            f'<summary>지역 전체 보기 — {len(SITE_CITIES)}개 시·군·구 · {total:,}곳</summary>'
            f'{"".join(blocks)}'
            f'<p><a href="{url("/parking/regions/")}">지역 전체 목록(구·동 페이지까지) 보기 →</a>'
            f' · <a href="{url("/parking/free/")}">무료 개방 주차장 →</a></p></details>')


